import sys

def morganAndString(a, b):
    result = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        if a[i:] < b[j:]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return ''.join(result)

def main():
    import sys
    input = sys.stdin.read().split()
    t = int(input[0])
    index = 1
    results = []
    for _ in range(t):
        a = input[index]
        b = input[index + 1]
        results.append(morganAndString(a, b))
        index += 2
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
